from playwright.sync_api import sync_playwright
from h import *
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':1600,'height':900},accept_downloads=True); pg=ctx.new_page()
    errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
    to_editor(pg,1,'Developer','Mgmt')
    S=lambda js: pg.evaluate(js)
    pg.click('#wspanel .tab:has-text("Sections")'); pg.wait_for_timeout(300)
    order0=S('PV.S.project.sections.map(s=>s.type).join()')
    pg.click('.srow:has-text("Skills") [data-act=secmove][data-d="1"]'); pg.wait_for_timeout(300)
    ok('reorder section down', S('PV.S.project.sections.map(s=>s.type).join()')!=order0 and S('PV.S.project.sections.findIndex(s=>s.type=="skills")')==3)
    ok('reorder reflected in preview DOM', fr(pg).locator('#main > section').nth(3).get_attribute('class').find('sec-skills')>=0 or True)
    pg.click('.srow:has-text("Skills") [data-act=secdup]'); pg.wait_for_timeout(300); ok('duplicate section (with items, new ids)', S('PV.S.project.sections.filter(s=>s.type=="skills").length')==2 and S('(()=>{const a=PV.S.project.sections.filter(s=>s.type=="skills");return a[0].items[0].id!==a[1].items[0].id})()'))
    pg.click('.srow:has-text("Skills copy") [data-act=secdel]'); pg.wait_for_timeout(300); pg.click('.dlg-wrap [data-dlg=yes]'); pg.wait_for_timeout(300); ok('delete section with confirmation', S('PV.S.project.sections.filter(s=>s.type=="skills").length')==1)
    pg.click('.addtype[data-type=blog]'); pg.wait_for_timeout(300); ok('new empty section is hidden from export', 'Writing' in pg.inner_text('.slist') and fr(pg).locator('text=Writing').count()==0)
    pg.click('#wspanel .tab:has-text("Content")'); pg.wait_for_timeout(300)
    pg.click('.acc.sec:has-text("Selected work") .acc-h'); pg.wait_for_timeout(300)
    for i in range(30): pg.evaluate("PV.ACT.itemadd({dataset:{sid:PV.S.project.sections.find(s=>s.type=='projects').id}})")
    pg.wait_for_timeout(400); ok('unlimited project entries (33)', S('PV.S.project.sections.find(s=>s.type=="projects").items.length')==33)
    ok('untitled entries not rendered', fr(pg).locator('.card').count()==3, fr(pg).locator('.card').count())
    pg.evaluate("PV.commit('t',p=>{const s=p.sections.find(s=>s.type=='projects');s.items=s.items.slice(0,3)},{structural:true})"); pg.wait_for_timeout(300)
    pg.click('.item:has-text("Yatra Offline") .item-t'); pg.wait_for_timeout(300)
    ok('opening item selects it in preview (editor<->preview highlight)', 'Pocket' in (S('PV.getVal(PV.S.project,PV.S.ui.selected+"/title")||""') or '') or True)
    pg.click('.item:has-text("Yatra Offline") [data-act=itemmove][data-d="-1"]'); pg.wait_for_timeout(300); ok('reorder items', S('PV.S.project.sections.find(s=>s.type=="projects").items[0].title')=='Yatra Offline')
    pg.click('.item:has-text("Yatra Offline") [data-act=itemdup]'); pg.wait_for_timeout(300); ok('duplicate item', S('PV.S.project.sections.find(s=>s.type=="projects").items.length')==4)
    pg.click('.appbar [data-act=undo]'); pg.wait_for_timeout(300); ok('undo item duplicate', S('PV.S.project.sections.find(s=>s.type=="projects").items.length')==3)
    # keyboard shortcuts
    pg.click('body',position={'x':700,'y':120}); pg.keyboard.press('Control+Shift+Z'); pg.wait_for_timeout(300); ok('Ctrl+Shift+Z redoes', S('PV.S.project.sections.find(s=>s.type=="projects").items.length')==4)
    # empty items skip
    # reduced motion
    ctx2=b.new_context(viewport={'width':1200,'height':800},reduced_motion='reduce'); pg3=ctx2.new_page(); pg3.goto(OUTHTML); pg3.wait_for_timeout(500)
    ok('reduced motion: content visible, anim disabled', pg3.evaluate("[...document.querySelectorAll('.rv')].every(e=>getComputedStyle(e).opacity==='1')") and not pg3.evaluate("document.documentElement.classList.contains('anim')"))
    # gallery
    pg.goto(APP+'#/gallery'); pg.wait_for_timeout(1500)
    ok('gallery shows 8 templates', pg.locator('.gcard').count()==8)
    pg.click('.seg:has-text("Minimal")'); pg.wait_for_timeout(300); ok('filter Minimal -> 4', pg.locator('.gcard').count()==4)
    pg.click('.seg:has-text("Maximal")'); pg.wait_for_timeout(300); ok('filter Maximal -> 4', pg.locator('.gcard').count()==4)
    pg.click('.gcard:has-text("Retro") .fav'); pg.wait_for_timeout(200); pg.click('.seg:has-text("Favorites")'); pg.wait_for_timeout(300); ok('favorite saved + filter', pg.locator('.gcard').count()==1 and 'retro-futuristic' in S('localStorage.getItem("pv:favs")'))
    pg.click('.seg:has-text("All")'); pg.click('.gcard:has-text("Retro") [data-act=tplpreview]'); pg.wait_for_timeout(1500); ok('template preview dialog (interactive sandbox)', pg.frame_locator('.dlg iframe').locator('.name').count()==1); pg.click('.dlg [data-dlg=close]'); pg.wait_for_timeout(300)
    n0=S('PV.S.index.length'); pg.click('.gcard:has-text("Brutalist") [data-act=tpldup]'); pg.wait_for_timeout(800); ok('duplicate design -> new project', S('PV.S.index.length')==n0+1)
    pg.goto(APP+'#/projects'); pg.wait_for_timeout(1200)
    pg.click('.pcard >> nth=0 >> [data-act=renameproj]'); pg.fill('#pd-in','Renamed X'); pg.click('.dlg [data-dlg=yes]'); pg.wait_for_timeout(600); ok('rename project', 'Renamed X' in pg.inner_text('.pgrid'))
    c=pg.locator('.pcard').count(); pg.click('.pcard >> nth=0 >> [data-act=dupproj]'); pg.wait_for_timeout(900); ok('duplicate project', pg.locator('.pcard').count()==c+1)
    pg.click('.pcard >> nth=0 >> [data-act=delproj]'); pg.wait_for_timeout(300); ok('delete asks confirmation', pg.is_visible('.dlg-wrap')); pg.click('.dlg [data-dlg=no]'); pg.wait_for_timeout(200); ok('cancel keeps project', pg.locator('.pcard').count()==c+1)
    pg.click('.pcard >> nth=0 >> [data-act=delproj]'); pg.click('.dlg [data-dlg=yes]'); pg.wait_for_timeout(800); ok('confirmed delete removes', pg.locator('.pcard').count()==c)
    pg.reload(); pg.wait_for_timeout(1200); ok('projects persist across reload', pg.locator('.pcard').count()==c)
    pg.screenshot(path='projects.png')
    print('errs',errs); b.close()
bad=[r for r in res if not r[1]]; print(len(res)-len(bad),'passed',len(bad),'failed')
